const baseState={version:4,view:'quiz',q:0,answers:Array(9).fill(null),birth:{date:'',time:'12:00',unknown:false,wrist:16,size:8},chart:null,recommended:[],selectionDetails:[],pureRecipes:[],mixedRecipe:[{id:0,n:16},{id:36,n:2},{id:45,n:2}],carouselIndex:0,result:false,libraryFilter:'全部',search:''};
