function stableHash(text){let h=2166136261;for(const ch of text){h^=ch.codePointAt(0);h=Math.imul(h,16777619)}return h>>>0}
function seededUnit(seed,name){return stableHash(`${seed}|${name}`)/4294967295}
function matchedKeywords(crystal,keywords){return keywords.filter(k=>crystal.meaning.includes(k)||crystal.texture.includes(k))}
function colorFamily(color){return(['黑','白','蓝','绿','红','粉','黄','金','紫','橙','灰','棕'].find(x=>color.includes(x))||color).slice(0,1)}
function chooseRecommendations(chart,a){
  const goal=goals[a[8]],profile=goalProfiles[a[8]],seed=`${state.birth.date}|${state.birth.time}|${a.join('')}|${chart.pillars.join('')}`;
  const ranked=crystals.map(crystal=>{
    let score=0;const reasons=[];
    if(crystal.element===chart.useGod){score+=5.4;reasons.push(`呼应${chart.useGod}用神倾向`)}
    if(crystal.element===chart.joyGod){score+=2.8;reasons.push(`兼顾${chart.joyGod}喜神方向`)}
    if(crystal.element===chart.least){score+=1.2;reasons.push(`补入表层偏少的${chart.least}元素`)}
    const goalElementIndex=profile.elements.indexOf(crystal.element);if(goalElementIndex>=0){score+=2.2-goalElementIndex*.35;reasons.push(`贴近「${goal.name}」的五行配色`)}
    if(goal.candidates.includes(crystal.name)){score+=2.2;reasons.push(`是「${goal.name}」的代表珠材`)}
    const goalHits=matchedKeywords(crystal,profile.keywords);if(goalHits.length){score+=Math.min(2.4,goalHits.length*1.2);reasons.push(`「${goalHits.slice(0,2).join('、')}」回应当前愿望`)}
    const traitHits=[];personalityProfiles.forEach((pair,i)=>{const p=pair[a[i]],hits=matchedKeywords(crystal,p.keywords);if(hits.length){score+=.58;traitHits.push(p.label)}});
    if(traitHits.length)reasons.push(`契合${traitHits.slice(0,2).join('、')}`);
    const isVivid=/红|橙|金|黄|紫|多彩|虹彩/.test(crystal.color);if((a[6]===2&&isVivid)||(a[6]===0&&!isVivid))score+=.65;else if(a[6]===1)score+=.25;
    score+=seededUnit(seed,crystal.name)*2.35;
    return{crystal,score,reasons,seedMatch:Math.round(seededUnit(seed,crystal.name)*100)}
  });
  const selected=[];
  while(selected.length<3){
    const pool=ranked.filter(x=>!selected.some(s=>s.crystal.id===x.crystal.id)&&!(selected.length===2&&selected.every(s=>s.crystal.element===x.crystal.element))).map(x=>({...x,adjusted:x.score-selected.reduce((p,s)=>p+(s.crystal.visual===x.crystal.visual?1.5:0)+(s.crystal.element===x.crystal.element?1.25:0)+(colorFamily(s.crystal.color)===colorFamily(x.crystal.color)?1.1:0),0)}));
    pool.sort((x,y)=>y.adjusted-x.adjusted||x.crystal.id-y.crystal.id);selected.push(pool[0]);
  }
  return selected.map((x,i)=>({id:x.crystal.id,score:+x.score.toFixed(2),reasons:x.reasons.slice(0,4),match:96-i*4}));
}
function generate(){const b=state.birth,[y,m,d]=b.date.split('-').map(Number),[h,mi]=b.time.split(':').map(Number),ec=Solar.fromYmdHms(y,m,d,b.unknown?12:h,mi,0).getLunar().getEightChar();ec.setSect(2);const pillars=[ec.getYear(),ec.getMonth(),ec.getDay(),b.unknown?'—':ec.getTime()],chars=pillars.filter(p=>p!=='—').join(''),counts=Object.fromEntries(['木','火','土','金','水'].map(x=>[x,[...chars].filter(ch=>stemElement[ch]===x||branchElement[ch]===x).length]));const dayStem=pillars[2][0],dayElement=stemElement[dayStem],monthBranch=pillars[1][1],seasonElement=({寅:'木',卯:'木',辰:'木',巳:'火',午:'火',未:'火',申:'金',酉:'金',戌:'金',亥:'水',子:'水',丑:'水'})[monthBranch],support=producer(dayElement),total=Object.values(counts).reduce((n,x)=>n+x,0),strengthPoints=counts[dayElement]+counts[support]+(seasonElement===dayElement?2:seasonElement===support?1:0),ratio=strengthPoints/(total+2);let strength,useGod,joyGod;if(ratio>.52){strength='偏强';useGod=produce[dayElement];joyGod=control[dayElement]}else if(ratio<.34){strength='偏弱';useGod=support;joyGod=dayElement}else{strength='相对平衡';useGod=Object.keys(counts).sort((a,z)=>counts[a]-counts[z])[0];joyGod=support}const least=Object.keys(counts).sort((a,z)=>counts[a]-counts[z])[0];state.chart={pillars,counts,dayStem,dayElement,seasonElement,strength,useGod,joyGod,least,ratio};const details=chooseRecommendations(state.chart,state.answers),totalBeads=Math.max(12,Math.round((b.wrist*10+5)/b.size)),accentTotal=Math.max(2,Math.floor(totalBeads*.2)),a1=Math.ceil(accentTotal/2),a2=accentTotal-a1;state.selectionDetails=details;state.recommended=details.map(x=>x.id);state.pureRecipes=details.map(x=>({id:x.id,n:totalBeads}));state.mixedRecipe=[{id:details[0].id,n:totalBeads-accentTotal},{id:details[1].id,n:a1},{id:details[2].id,n:a2}];state.carouselIndex=0;state.result=true;sessionStorage.setItem('jingyu-result-v4',JSON.stringify(state))}
