function poemChoice(list,seed,key){return list[stableHash(`${seed}|${key}`)%list.length]}
function generatePoem(chart,a){const seed=`${state.birth.date}|${state.birth.time}|${a.join('')}|${chart.pillars.join('')}`,lines=[poemChoice(poemLines.day[chart.dayElement],seed,'day'),poemChoice(poemLines.use[chart.useGod],seed,'use'),poemChoice(poemLines.goal[a[8]],seed,'goal'),poemChoice(poemLines.end,seed,'end')],goalGuidance=[`你眼下像在整理一只将要远行的船：并非没有水路，而是船舱里装得太满。先看清哪些资源正在漏走，再把力气留给真正会生长的事情。积累不必声势很大，能守住、能重复，便是在聚水成川。`,`你已经站在起风的岸边，难处不在没有方向，而在想同时照顾太多航线。选定一件最值得推进的事，让它先驶出港口。行动会替你带回新的地图，途中修正也比停在岸上更接近答案。`,`此刻的心像被风吹皱的水面，越急着按平，波纹越密。先减少不必要的回应，给每天留下一小段无人催促的时间。水静之后，真正重要的声音会自己浮上来；你需要的不是更用力，而是重新找回自己的节拍。`,`关系像两个人同舟过水：靠得太远，听不见彼此；靠得太近，又容易挤乱脚步。眼下适合把期待说得更清楚，也允许对方按自己的速度回应。好的靠近不是猜中彼此，而是愿意一次次校准方向。`,`你并不是没有话，只是常在开口前把一句话反复打磨。眼下更需要一支先吹响的笛子，而不是一篇无可挑剔的乐谱。先说出最真实的一层，声音会在回应里慢慢变得清楚。`,`你走的像是一条入山石径，前方看不见全貌，很容易误以为自己没有进展。不要频繁换路，把一个问题学深、做出一份可见的成果。脚下每一阶都算数，走过的路终会连成山脊。`],energyHint=[`先回到安静处，并不是退缩，而是在把散落的心力收回来。`,`把真正的困惑交给一位可信的人，往往比独自推演更容易看见出口。`,`别把自己关得太久；走动、交谈和真实的现场，会让停滞重新流动。`],actionHint=[`看清水势再落桨，但给思考设一个期限，别让准备变成停泊。`,`不必等万事俱备，每天推进一小段，方向会在脚下逐渐清晰。`,`势起时可以向前，也要给自己留一处转舵的余地。`];return{lines,guidance:`${goalGuidance[a[8]]}${energyHint[a[0]]}${actionHint[a[1]]}`}}
