const branchImages={子:'子水临夜，感受往往藏得深',丑:'丑土含湿，习惯把变化慢慢消化',寅:'寅木初生，内里总有向前开路的冲动',卯:'卯木舒展，对关系和环境的细微变化很敏锐',辰:'辰土蓄水，常把多种念头收在心里反复衡量',巳:'巳火渐盛，内在有清楚的热望和行动欲',午:'午火当空，情绪与热爱来得直接而鲜明',未:'未土藏木，温和之中保留着自己的坚持',申:'申金初肃，遇事会很快进入判断和取舍',酉:'酉金成器，在意分寸、品质与是否值得',戌:'戌土守火，外表沉稳，心里仍护着一团热望',亥:'亥水归藏，想象、直觉与未说出口的感受都很丰富'};
function elementRelation(day,target){if(target===day)return['比劫','自我意志、同伴关系与边界'];if(produce[target]===day)return['印星','学习、支持、安全感与内在滋养'];if(produce[day]===target)return['食伤','表达、创造、输出与把想法落地'];if(control[day]===target)return['财星','资源、取舍、经营与现实成果'];return['官杀','规则、责任、压力与行动上的约束力']}
function renderPureCarousel(){const track=$('#pureTrack');state.carouselIndex=Math.min(state.carouselIndex||0,state.pureRecipes.length-1);track.innerHTML=state.pureRecipes.map((r,i)=>`<section class="carousel-slide" aria-label="${crystals[r.id].name}单色手串"><div class="result-stage"><canvas id="pureCanvas${i}" width="900" height="900"></canvas></div><p class="slide-caption">${crystals[r.id].name} · ${r.n} 颗 · ${state.birth.size} mm</p></section>`).join('');state.pureRecipes.forEach((r,i)=>drawBracelet($(`#pureCanvas${i}`),[r]));$('#pureDots').innerHTML=state.pureRecipes.map((r,i)=>`<button aria-label="查看${crystals[r.id].name}" data-slide="${i}"></button>`).join('');const setSlide=(index,scroll=true)=>{state.carouselIndex=(index+state.pureRecipes.length)%state.pureRecipes.length;document.querySelectorAll('#pureDots button').forEach((dot,i)=>dot.classList.toggle('active',i===state.carouselIndex));const recipe=state.pureRecipes[state.carouselIndex],crystal=crystals[recipe.id];$('#pureLegend').innerHTML=legend([recipe]);$('#pureReason').textContent=`${crystal.name}单独成串，以「${crystal.meaning}」作为这款的设计主题。左右滑动可查看另外两款。`;if(scroll)track.scrollTo({left:state.carouselIndex*track.clientWidth,behavior:'smooth'})};$('#purePrev').onclick=()=>setSlide(state.carouselIndex-1);$('#pureNext').onclick=()=>setSlide(state.carouselIndex+1);document.querySelectorAll('#pureDots button').forEach(b=>b.onclick=()=>setSlide(+b.dataset.slide));let scrollTimer;track.onscroll=()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>setSlide(Math.round(track.scrollLeft/Math.max(track.clientWidth,1)),false),70)};setSlide(state.carouselIndex,false)}
function renderResult(){const a=state.answers,c=state.chart,goal=goals[a[8]],recs=state.recommended.map(id=>crystals[id]),[useRole,useTheme]=elementRelation(c.dayElement,c.useGod),dayBranch=c.pillars[2][1];if(!state.selectionDetails?.length)state.selectionDetails=chooseRecommendations(c,a);$('#resultSummary').hidden=true;$('#resultTraits').innerHTML=[topKeywords[0][a[0]],topKeywords[1][a[1]],topKeywords[2][a[4]],goalKeywords[a[8]]].map(t=>`<span>${t}</span>`).join('');const poem=generatePoem(c,a);$('#resultPoem').innerHTML=poem.lines.map(line=>`<span>${line}</span>`).join('');$('#poemExplanation').innerHTML=`<p>${poem.guidance}</p>`;$('#pillars').innerHTML=c.pillars.map((p,i)=>`<div class="pillar"><small>${['年柱','月柱','日柱','时柱'][i]}</small><b>${p}</b></div>`).join('');$('#reportHighlights').innerHTML=`<div><small>日主</small><strong>${c.dayStem}${c.dayElement}</strong><p>性情与节奏的起点</p></div><div><small>命局倾向</small><strong>${c.strength}</strong><p>${c.seasonElement}气当令下的表层状态</p></div><div class="gold-highlight"><small>用神倾向</small><strong>${c.useGod}</strong><p>此刻适合补入的平衡方向</p></div><div><small>喜神倾向</small><strong>${c.joyGod}</strong><p>可从旁协助的第二方向</p></div>`;const max=Math.max(...Object.values(c.counts),1);$('#elementBars').innerHTML=Object.entries(c.counts).map(([k,v])=>`<div class="element-row"><span>${k}</span><div><i style="width:${v/max*100}%"></i></div><b>${v}</b></div>`).join('');$('#reportNarrative').innerHTML=`<p><strong>日主与气质</strong>你是${stemPolarity[c.dayStem]}${c.dayStem}${c.dayElement}日主，${dayPortrait[c.dayElement]}。阴阳属性让这种气质更偏向${stemPolarity[c.dayStem]==='阳'?'主动显露、由外而内地确认方向':'含蓄积累、由内而外地寻找时机'}。</p><p><strong>月令与旺衰</strong>出生月令以${c.seasonElement}气为主，四柱表层呈${c.strength}。五行不是缺什么就机械补什么，而要看日主能否承接；因此这里以${c.useGod}为用、${c.joyGod}为喜，让过盛处有出口、偏弱处得承托。</p><p><strong>日支内景</strong>日柱为${c.pillars[2]}，日支落${dayBranch}。传统命理常把日支看作贴近内心与亲密关系的位置：${branchImages[dayBranch]}。这部分不一定直接表现出来，却容易在独处、选择伴侣或真正放松时浮现。</p><p><strong>用神落点</strong>${c.useGod}与${c.dayElement}之间形成${useRole}关系，传统语义指向${useTheme}。所以你此刻真正要补的并非一种颜色，而是相应的生活动作：${useRole==='印星'?'允许自己求助、学习并被支持':useRole==='食伤'?'把想法说出来、做出来，让能量有出口':useRole==='财星'?'整理资源、明确取舍，并让投入留下结果':useRole==='官杀'?'建立规则和边界，把压力变成清晰的行动顺序':'稳住自我立场，也学会与同伴分工'}。</p><p><strong>性格与当下</strong>${pacePortrait[a[1]]}${tensionPortrait[a[0]]}${a[5]===0?'你已经意识到需要放慢，却可能仍对休息抱有负担感。':a[5]===1?'你想稳定向前，真正需要的是可重复的小步骤，而不是一次改变全部。':'你已经积蓄了行动欲，接下来要防止用速度掩盖尚未想清楚的取舍。'}</p><p><strong>眼下所求</strong>你选择了「${goal.name}」。这更像是在说，你希望${goal.effect.replace('希望','')}把它当成接下来一段时间的主线，会比同时追赶许多目标更有力量。</p>`;$('#chartNote').innerHTML=`表层五行：${Object.entries(c.counts).map(([k,v])=>`${k} ${v}`).join(' · ')}。${state.birth.unknown?'时辰未知，未纳入时柱。':''} 喜用神为轻量文化推演，不等同于专业命理定盘。`;$('#recommendedMaterials').innerHTML=recs.map((x,i)=>{const detail=state.selectionDetails.find(d=>d.id===x.id)||{reasons:[`综合命盘、愿望与性格后进入前三`],match:80};return`<article class="recommend-card"><span class="recommend-no">0${i+1}</span>${bead(x.id)}<div><p class="eyebrow">综合匹配 ${detail.match}%</p><h3>${x.name}</h3><p>${detail.reasons.join('；')}。它的设计关键词是「${x.meaning}」。</p><small>${x.texture}</small></div></article>`}).join('');$('#mixedLegend').innerHTML=legend(state.mixedRecipe);renderPureCarousel();const pct=Math.round(state.mixedRecipe[0].n/state.mixedRecipe.reduce((n,r)=>n+r.n,0)*100);$('#mixedReason').textContent=`综合分最高的${recs[0].name}占 ${pct}% 作为主色，${recs[1].name}与${recs[2].name}各自克制点缀，让命盘、愿望与性格共同参与同一串配色。`;drawBracelet($('#mixedBracelet'),state.mixedRecipe);document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>downloadDesign(b.dataset.download))}
function balancedSequence(recipe){const total=recipe.reduce((n,r)=>n+r.n,0),seq=Array(total).fill(recipe[0].id),accents=[];recipe.slice(1).forEach(r=>{for(let i=0;i<r.n;i++)accents.push(r.id)});accents.forEach((id,i)=>{seq[Math.floor(i*total/accents.length)%total]=id});return seq}
function drawBead(ctx,id,x,y,size){const c=crystals[id],sw=sprite.naturalWidth/4,sh=sprite.naturalHeight/4;ctx.save();ctx.shadowColor='#0008';ctx.shadowBlur=12;ctx.shadowOffsetY=7;ctx.filter=c.filter;ctx.drawImage(sprite,c.visual%4*sw,Math.floor(c.visual/4)*sh,sw,sh,x-size/2,y-size/2,size,size);ctx.restore()}
function drawBracelet(canvas,recipe){if(!canvas||!sprite.complete||!sprite.naturalWidth)return;const ctx=canvas.getContext('2d'),ids=balancedSequence(recipe),n=ids.length,radius=295,size=Math.min(130,2*Math.PI*radius/n*1.2);ctx.clearRect(0,0,900,900);ids.forEach((id,i)=>{const a=-Math.PI/2+i/n*Math.PI*2;drawBead(ctx,id,450+Math.cos(a)*radius,450+Math.sin(a)*radius,size)})}
function updatePreview(){const recipe=state.result?state.mixedRecipe:[{id:0,n:16},{id:36,n:2},{id:45,n:2}];$('#designName').textContent=state.result?'三晶共鸣 · 配色单串':'静谧 · 微光';$('#beadSpec').textContent=`${recipe.reduce((n,r)=>n+r.n,0)} 颗 / ${state.birth.size} mm`;$('#legend').innerHTML=legend(recipe);$('#previewNote').textContent=state.result?'三种推荐晶石，主色约 80%，其余对称点缀。':'示例搭配。完成探索后，为你生成完整分析和两种方案。';drawBracelet($('#bracelet'),recipe)}
function downloadDesign(type){if(!sprite.naturalWidth){alert('珠材图片还未加载，请稍后再试。');return}const pureIndex=state.carouselIndex||0,source=type==='pure'?$(`#pureCanvas${pureIndex}`):$('#mixedBracelet'),recipe=type==='pure'?[state.pureRecipes[pureIndex]]:state.mixedRecipe,c=document.createElement('canvas');c.width=1200;c.height=1450;const ctx=c.getContext('2d');ctx.fillStyle='#172425';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(source,100,120,1000,1000);ctx.textAlign='center';ctx.fillStyle='#d8ba80';ctx.font='34px serif';ctx.fillText(`晶遇 · ${type==='pure'?'单色系列':'配色单串版'}`,600,95);ctx.fillStyle='#f1efe7';ctx.font='25px sans-serif';ctx.fillText(recipe.map(r=>`${crystals[r.id].name} ${r.n}颗`).join('  ·  '),600,1215);ctx.font='22px sans-serif';ctx.fillText(`${state.birth.size} mm · 手围 ${state.birth.wrist} cm`,600,1270);ctx.fillStyle='#a2b0ab';ctx.font='19px sans-serif';ctx.fillText('AI 材质示意 · 文化寓意与个人审美参考',600,1350);const a=document.createElement('a');a.download=`晶遇-${type==='pure'?crystals[recipe[0].id].name+'单色手串':'配色单串版'}.png`;a.href=c.toDataURL('image/png');a.click()}
function library(filter=state.libraryFilter,query=state.search){state.libraryFilter=filter;state.search=query;const choices=['全部','石英水晶','玛瑙玉髓','长石','矿物晶石','火山玻璃'];$('#filters').innerHTML=choices.map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f}</button>`).join('');const list=crystals.filter(c=>(filter==='全部'||c.category===filter)&&(c.name.includes(query)||c.color.includes(query)||c.meaning.includes(query)));$('#libraryCount').textContent=list.length;$('#catalog').innerHTML=list.length?list.map(c=>`<button class="crystal-card" data-id="${c.id}">${bead(c.id)}<h3>${c.name}</h3><p>${c.category} · ${c.element} · ${c.color}</p><small>${c.meaning}</small></button>`).join(''):'<p class="empty">没有找到匹配的晶石，换个关键词试试。</p>';document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>library(b.dataset.filter,state.search));document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetail(+b.dataset.id))}
function openDetail(id){const c=crystals[id];$('#detailBody').innerHTML=`${bead(c.id)}<p class="eyebrow">CRYSTAL NO. ${String(c.id+1).padStart(2,'0')}</p><h2>${c.name}</h2><p>${c.texture}</p><p>类别：${c.category}<br>颜色：${c.color} · 五行配色：${c.element}<br>设计寓意：${c.meaning}<br>常用珠径：6 / 8 / 10 / 12 mm</p><p>寓意用于个人审美和自我提醒，不代表晶石具有改变运势或治疗疾病的功效。</p>`;$('#detail').showModal()}
function openLibrary(){if(!$('#resultPage').hidden)show('birth');$('#library').hidden=false;library();$('#library').scrollIntoView({behavior:'smooth'})}
sprite.onload=()=>{$('#artStatus').hidden=true;updatePreview();if(state.result)renderResult()};sprite.onerror=()=>{$('#artStatus').textContent='珠材示意图暂不可用，请刷新重试'};$('#libraryTop').onclick=openLibrary;$('#resultLibrary').onclick=openLibrary;$('#closeLibrary').onclick=()=>{$('#library').hidden=true;window.scrollTo({top:0,behavior:'smooth'})};$('#crystalSearch').oninput=e=>library(state.libraryFilter,e.target.value.trim());$('#closeDetail').onclick=()=>$('#detail').close();$('#resultBack').onclick=()=>show('birth');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));window.onpopstate=()=>show(location.hash==='#result'?'result':location.hash==='#birth'?'birth':'quiz',false);if(location.hash==='#result'&&state.result)show('result',false);else{if(location.hash==='#result')history.replaceState({view:'quiz'},'','#quiz');renderQuiz();updatePreview()}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_crystal_profile',description:'读取当前命盘倾向、推荐晶石与两种手串方案，不改变页面。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw Error('参数必须为空对象');return{completed:state.result,chart:state.chart?{dayMaster:state.chart.dayStem+state.chart.dayElement,useGod:state.chart.useGod,joyGod:state.chart.joyGod}:null,goal:state.answers[8]!==null?goals[state.answers[8]].name:null,recommended:state.recommended.map(id=>crystals[id].name),singleColor:state.pureRecipes.map(r=>({name:crystals[r.id].name,count:r.n})),mixed:state.mixedRecipe.map(r=>({name:crystals[r.id].name,count:r.n}))}}})).catch(()=>{})}catch{}}
